 "content": "from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Find a horizontal color key: at least two identical nonzero rows.
    patterns = {}
    for y, row in enumerate(g):
        vals = tuple((x, c) for x, c in enumerate(row) if c != 0)
        if len(vals) >= 2:
            patterns.setdefault(vals, []).append(y)
    candidates = [(ys, vals) for vals, ys in patterns.items() if len(ys) >= 2]
    if not candidates:
        return g
    ys, vals = max(candidates, key=lambda z: (len(z[0]), len(z[1])))
    palette = [c for _, c in vals]
    # Locate the connected template of the key's central color, excluding the key itself.
    target = palette[len(palette)//2]
    key_rows = set(ys)
    seen = set()
    comps = []
    for y in range(h):
        for x in range(w):
            if g[y][x] != target or y in key_rows or (y,x) in seen:
                continue
            q = [(y,x)]; seen.add((y,x)); comp=[]
            while q:
                cy,cx=q.pop(); comp.append((cy,cx))
                for ny,nx in ((cy-1,cx),(cy+1,cx),(cy,cx-1),(cy,cx+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and g[ny][nx] == target and ny not in key_rows:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append(comp)
    if not comps:
        return g
    comp = max(comps, key=len)
    miny=min(y for y,x in comp); maxy=max(y for y,x in comp)
    minx=min(x for y,x in comp); maxx=max(x for y,x in comp)
    mask={(y-miny,x-minx) for y,x in comp}
    step=maxy-miny+1
    # Repaint vertically stacked instances in the color-key order, anchored on its matching instance.
    mid=palette.index(target)
    for i,color in enumerate(palette):
        top=miny+(i-mid)*step
        for dy,dx in mask:
            yy,xx=top+dy,minx+dx
            if 0 <= yy < h and 0 <= xx < w:
                g[yy][xx]=color
    return g
